function languageSwitch(code) {
  return ['ru','en','uz','tg','es','id'].map(key => {
    if (key === code) return `<span class="active" data-lang="${key}">${labels[key]}</span>`;
    const href = code === 'ru' ? `${key}/${slug}` : key === 'ru' ? `../${slug}` : `../${key}/${slug}`;
    return `<a data-lang="${key}" href="${href}">${labels[key]}</a>`;
  }).join('');
}

